(5433049, 780514, 36133, '<td valign="top">Although centering is a no-no on DPC, I think it might have helped this image. If the model was a little bit to the left and the vegetation on the right excluded, this would be a lot stronger.</td>', 'Although centering is a no-no on DPC, I think it might have helped this image. If the model was a little bit to the left and the vegetation on the right excluded, this would be a lot stronger.', '2009-04-12 13:58:35.000000', NULL, 1),
(5433388, 780281, 98141, '<td valign="top">This pose looks really unnatural to me. Also, it came out quite grainy. I think for stock photos color would have worked better. The lighting looks good.</td>', 'This pose looks really unnatural to me. Also, it came out quite grainy. I think for stock photos color would have worked better. The lighting looks good.', '2009-04-12 19:38:11.000000', NULL, 1),
(5433390, 779748, 98141, '<td valign="top">Great, diffused lighting and interesting perspective. Could definitely work as a stock photo.</td>', 'Great, diffused lighting and interesting perspective. Could definitely work as a stock photo.', '2009-04-12 19:38:48.000000', NULL, 1),
(5433394, 780474, 98141, '<td valign="top">Would work GREAT as a stock photo, lighting is great and it definitely corresponds with "fitness."</td>', 'Would work GREAT as a stock photo, lighting is great and it definitely corresponds with "fitness."', '2009-04-12 19:39:35.000000', NULL, 1),
(5433400, 780086, 98141, '<td valign="top">Great shot. Perfect for stock: well-lit with excellently diffused lighting. And definitely fitness-oriented. I think this will be top 10 for sure.</td>', 'Great shot. Perfect for stock: well-lit with excellently diffused lighting. And definitely fitness-oriented. I think this will be top 10 for sure.', '2009-04-12 19:40:20.000000', NULL, 1),
(5433401, 780088, 98141, '<td valign="top">Love the colors in the background (sky?), great, sharp silhouette! One of my top 3 from this challenge.</td>', 'Love the colors in the background (sky?), great, sharp silhouette! One of my top 3 from this challenge.', '2009-04-12 19:40:26.000000', NULL, 1),
