(5436599, 780203, 80104, '<td valign="top">This is very interesting shot.  I take it if it was any sharper it would show imperfections in the skin?  Highlights in the hair really do this picture justice.</td>', 'This is very interesting shot.  I take it if it was any sharper it would show imperfections in the skin?  Highlights in the hair really do this picture justice.', '2009-04-14 13:03:31.000000', NULL, 1),
(5436600, 780088, 80104, '<td valign="top">Very cool photo.  I could see that on the cover of a magazine.</td>', 'Very cool photo.  I could see that on the cover of a magazine.', '2009-04-14 13:03:33.000000', NULL, 1),
(5436601, 780286, 80104, '<td valign="top">Interesting shot, not my cup of tea but the reflection on her hand is eye catching.</td>', 'Interesting shot, not my cup of tea but the reflection on her hand is eye catching.', '2009-04-14 13:03:56.000000', NULL, 1),
(5436602, 780514, 80104, '<td valign="top">Nice.  Wish the contrast was just a tad stronger though but very nice capture.  A 7</td>', 'Nice.  Wish the contrast was just a tad stronger though but very nice capture.  A 7', '2009-04-14 13:03:58.000000', NULL, 1),
(5436603, 780512, 80104, '<td valign="top">Nice, simple, color and lighting is nice.  Wish there was a bit more light on the face from the left side to the center without more highlight.</td>', 'Nice, simple, color and lighting is nice.  Wish there was a bit more light on the face from the left side to the center without more highlight.', '2009-04-14 13:04:01.000000', NULL, 1),
(5436604, 779958, 80104, '<td valign="top">Well done.  Too bad you couldn''t crop a bit more.  7</td>', 'Well done.  Too bad you couldn''t crop a bit more.  7', '2009-04-14 13:04:04.000000', NULL, 1),
(5436606, 780089, 80104, '<td valign="top">I wish the focus wasn''t quite as soft in this photo.  You know you''re suppose to be standing up to play Wii games huh?  here''s a trick if you find yourself sitting to play most games, move the couch far back enough that the remote doesn''t work well while sitting :-D</td>', 'I wish the focus wasn''t quite as soft in this photo.  You know you''re suppose to be standing up to play Wii games huh?  here''s a trick if you find yourself sitting to play most games, move the couch far back enough that the remote doesn''t work well while sitting :-D', '2009-04-14 13:04:55.000000', NULL, 1),
(5436610, 780012, 80104, '<td valign="top">Nice shot.  The white background helps seperate the subject from anything that could be distracting.</td>', 'Nice shot.  The white background helps seperate the subject from anything that could be distracting.', '2009-04-14 13:05:36.000000', NULL, 1),
(5436612, 779097, 80104, '<td valign="top">Nicely done.  The whites seem a tad bright in this one but it''s great nonetheless.  Too bad the coffee cup is so bright it blends with the logo behind it on the shirt.  The desaturation works on this one.</td>', 'Nicely done.  The whites seem a tad bright in this one but it''s great nonetheless.  Too bad the coffee cup is so bright it blends with the logo behind it on the shirt.  The desaturation works on this one.', '2009-04-14 13:06:29.000000', NULL, 1),
(5436613, 780419, 80104, '<td valign="top">This photo doesn''t work for me.  This could have used a different angle if possible, maybe from below looking up to get a bit of the sky in the shot?  The subject doesn''t stand out as much as I''d like.</td>', 'This photo doesn''t work for me.  This could have used a different angle if possible, maybe from below looking up to get a bit of the sky in the shot?  The subject doesn''t stand out as much as I''d like.', '2009-04-14 13:07:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5436614, 780474, 80104, '<td valign="top">Yeah, that''s how I feel.  Interesting shot.  Perfect as a stock photo.  Maybe a tad bit of sharpening could have helped this image along.</td>', 'Yeah, that''s how I feel.  Interesting shot.  Perfect as a stock photo.  Maybe a tad bit of sharpening could have helped this image along.', '2009-04-14 13:07:49.000000', NULL, 1),
(5436615, 780032, 80104, '<td valign="top">Although the shot doesn''t really meet the challenge I didn''t take away points for that.  The shot is well done.  The background they''re sitting on is a little distracting in the foreground but otherwise the image works.</td>', 'Although the shot doesn''t really meet the challenge I didn''t take away points for that.  The shot is well done.  The background they''re sitting on is a little distracting in the foreground but otherwise the image works.', '2009-04-14 13:08:45.000000', NULL, 1),
(5436617, 779930, 80104, '<td valign="top">Great shot.  The angle works and the fast shutter helps stop the action well.</td>', 'Great shot.  The angle works and the fast shutter helps stop the action well.', '2009-04-14 13:09:07.000000', NULL, 1),
(5436620, 780519, 80104, '<td valign="top">This could have used a bit of sharpening imo.  Background works for it as a stock photo but I wish the text on the weight would pop out just a bit more at me.</td>', 'This could have used a bit of sharpening imo.  Background works for it as a stock photo but I wish the text on the weight would pop out just a bit more at me.', '2009-04-14 13:09:42.000000', NULL, 1),
(5436621, 779603, 80104, '<td valign="top">Great image.  preparing for battle.  Well captured.  Lighting is great and I believe the tone you gave this image works too.</td>', 'Great image.  preparing for battle.  Well captured.  Lighting is great and I believe the tone you gave this image works too.', '2009-04-14 13:10:17.000000', NULL, 1),
(5436623, 780415, 80104, '<td valign="top">The image could use a bit more lighting on the subject versus the left of the subject.  Also a bit more sharpness to the apple would have worked(Aperture maybe)</td>', 'The image could use a bit more lighting on the subject versus the left of the subject.  Also a bit more sharpness to the apple would have worked(Aperture maybe)', '2009-04-14 13:11:03.000000', NULL, 1),
(5436625, 779379, 80104, '<td valign="top">Very neat capture.  Perfect for a stock.  Lighting is great as well as the stopped action.  Not a hint of bluriness.</td>', 'Very neat capture.  Perfect for a stock.  Lighting is great as well as the stopped action.  Not a hint of bluriness.', '2009-04-14 13:11:39.000000', NULL, 1),
(5436629, 780322, 80104, '<td valign="top">Interesting photo shoot on this one.  Too bad about the few imperfections from the background and foreground.  They''d be out in post processing of course if this wasn''t a basic challenge.</td>', 'Interesting photo shoot on this one.  Too bad about the few imperfections from the background and foreground.  They''d be out in post processing of course if this wasn''t a basic challenge.', '2009-04-14 13:12:40.000000', NULL, 1),
(5436631, 780550, 80104, '<td valign="top">This is a good capture and comical at that.  Lighting seems good as well as the color.</td>', 'This is a good capture and comical at that.  Lighting seems good as well as the color.', '2009-04-14 13:13:02.000000', NULL, 1),
(5436635, 779991, 80104, '<td valign="top">Interesting shot, too bad you couldn''t get a bit more sharpness from the subject(tough one I know).  The border works for this image.</td>', 'Interesting shot, too bad you couldn''t get a bit more sharpness from the subject(tough one I know).  The border works for this image.', '2009-04-14 13:13:41.000000', NULL, 1),
(5436636, 780145, 80104, '<td valign="top">Well lit image.  B&amp;W works on this one.  Sharp as well.</td>', 'Well lit image.  B&W works on this one.  Sharp as well.', '2009-04-14 13:13:56.000000', NULL, 1),
(5436638, 780086, 80104, '<td valign="top">Interesting setup and perspective.  Wish the left shoe was a bit sharper in places then it is.</td>', 'Interesting setup and perspective.  Wish the left shoe was a bit sharper in places then it is.', '2009-04-14 13:14:27.000000', NULL, 1),
(5436639, 779567, 80104, '<td valign="top">Nice work except the colors seem a bit too blah too me.  Guess you can only blame winter for that.  Saturation?  Maybe a bit more contrast.</td>', 'Nice work except the colors seem a bit too blah too me.  Guess you can only blame winter for that.  Saturation?  Maybe a bit more contrast.', '2009-04-14 13:15:01.000000', NULL, 1),
(5436643, 780552, 80104, '<td valign="top">Nice sharp capture of your moving subject(unless she''s got a bolt in her back holding her in place.  I don''t know if having her off center makes for as nice a picture in this case.</td>', 'Nice sharp capture of your moving subject(unless she''s got a bolt in her back holding her in place.  I don''t know if having her off center makes for as nice a picture in this case.', '2009-04-14 13:15:55.000000', NULL, 1),
(5436644, 780234, 80104, '<td valign="top">Nice shot.  Wishing the ball was a bit more in focus.  Other then that, lighting is good, background works and colors are fine.</td>', 'Nice shot.  Wishing the ball was a bit more in focus.  Other then that, lighting is good, background works and colors are fine.', '2009-04-14 13:16:21.000000', NULL, 1),
(5436646, 779061, 80104, '<td valign="top">Interesting shot.  I find the back of the chair too burnt out but it''s an interesting take on the challenge nonetheless.</td>', 'Interesting shot.  I find the back of the chair too burnt out but it''s an interesting take on the challenge nonetheless.', '2009-04-14 13:16:53.000000', NULL, 1),
(5436649, 780066, 80104, '<td valign="top">Your boat sticks out but your subject kind of fades with the rest of the picture.  Wish you could bring him out just a bit more.  Maybe a crop?  More contrast?</td>', 'Your boat sticks out but your subject kind of fades with the rest of the picture.  Wish you could bring him out just a bit more.  Maybe a crop?  More contrast?', '2009-04-14 13:17:48.000000', NULL, 1),
(5436653, 780489, 80104, '<td valign="top">I do like the shot.  The skin seems a bit too dark for me.  Blame the hair but it''s sharp and the carots work.</td>', 'I do like the shot.  The skin seems a bit too dark for me.  Blame the hair but it''s sharp and the carots work.', '2009-04-14 13:18:41.000000', NULL, 1),
(5436655, 780518, 80104, '<td valign="top">Interesting shot.  I kind of wish the faces could be lit up just a bit on this shot.</td>', 'Interesting shot.  I kind of wish the faces could be lit up just a bit on this shot.', '2009-04-14 13:19:07.000000', NULL, 1),
(5436658, 780390, 80104, '<td valign="top">The wide shot works for this one to get everyone in there.  Nice crop.  Wish there was a bit more definition to the faces but you''d probably need a bigger picture to get that from it.</td>', 'The wide shot works for this one to get everyone in there.  Nice crop.  Wish there was a bit more definition to the faces but you''d probably need a bigger picture to get that from it.', '2009-04-14 13:19:55.000000', NULL, 1),
(5436660, 780488, 80104, '<td valign="top">Very simplistic shot that works.  Nothing overwhelming but it meets the theme.  Maybe a bit less reflection on the dumbells.</td>', 'Very simplistic shot that works.  Nothing overwhelming but it meets the theme.  Maybe a bit less reflection on the dumbells.', '2009-04-14 13:20:35.000000', NULL, 1),
(5436664, 780534, 80104, '<td valign="top">Very interesting shot.  Just about feels like I''m looking at a shot to be used in a newspaper under a headline: "such and such a player has been using steroids."  The feeling shows.</td>', 'Very interesting shot.  Just about feels like I''m looking at a shot to be used in a newspaper under a headline: "such and such a player has been using steroids."  The feeling shows.', '2009-04-14 13:21:18.000000', NULL, 1),
