(5436667, 779920, 80104, '<td valign="top">Wished the blacks were more black.  Contrast.  The screen is distracting in this image.</td>', 'Wished the blacks were more black.  Contrast.  The screen is distracting in this image.', '2009-04-14 13:22:31.000000', NULL, 1),
(5436669, 780130, 80104, '<td valign="top">Interesting shot.  Nothing over-appealing but it''s sharp, the lighting works and the image would work as a stock.</td>', 'Interesting shot.  Nothing over-appealing but it''s sharp, the lighting works and the image would work as a stock.', '2009-04-14 13:22:57.000000', NULL, 1),
(5436671, 779491, 80104, '<td valign="top">There''s my shoes.  Well mine are in better shape and they''re black.  Nice lighting and background.  Well sharpened.</td>', 'There''s my shoes.  Well mine are in better shape and they''re black.  Nice lighting and background.  Well sharpened.', '2009-04-14 13:23:28.000000', NULL, 1),
